function apiOrigin() {
  return (process.env.ALPHALAB_API_ORIGIN || 'http://127.0.0.1:8000').replace(/\/+$/, '')
}

async function run(input) {
  const profile = input.profile === 'runtime' ? 'runtime' : 'demo'
  const body = {
    name: String(input.name || '').trim(),
    expression: String(input.expression || '').trim(),
    profile,
  }
  if (input.start_date) body.start_date = String(input.start_date).trim()
  if (input.end_date) body.end_date = String(input.end_date).trim()
  const response = await fetch(apiOrigin() + '/api/market/custom-risk-factor/evaluate', {
    method: 'POST',
    headers: { Accept: 'application/json', 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  })
  if (!response.ok) throw new Error('AlphaLab API ' + response.status + ': ' + await response.text())
  return response.json()
}
